-- Uploaded media (POST /media) and the images of profiles and communities
-- (PUT /users/me/avatar, PUT /communities/:name/icon and /banner).
-- media holds one row per stored object. storage_key is the object's key in
-- the configured storage (MEDIA_STORAGE), generated by the API. purpose says
-- what the file was processed for: 'post' files keep their dimensions,
-- profile images are normalised to fixed sizes. width and height are NULL
-- for a video. uploader_id is ON DELETE SET NULL, but accounts are
-- anonymised rather than deleted, and account deletion releases their media.
-- A file is in use while a row references it: posts.media_id,
-- users.avatar_media_id, communities.icon_media_id or banner_media_id. Each
-- reference is UNIQUE, so one file serves one place. The foreign keys keep
-- the default RESTRICT: a media row cannot be deleted while referenced, so
-- the cleanup sweep can never delete a file in use.
-- released_at marks a file for deletion: set when its post, account or
-- community is deleted, when it is replaced or removed, or by the sweep for
-- an upload never attached within MEDIA_PENDING_TTL_HOURS. The sweep deletes
-- the object, then the row. idx_media_released serves the sweep;
-- idx_media_uploader_pending the per-account pending cap and account deletion.
-- No existing row changes; every new column is NULL.
--
-- Not safely re-runnable after partial application: MySQL DDL is not
-- transactional. After a failure, inspect in statement order and complete the
-- rest manually before recording this version:
--   1. SHOW CREATE TABLE media: the table, its two indexes, fk_media_uploader.
--   2. SHOW CREATE TABLE posts: media_id, uq_posts_media_id, fk_posts_media.
--   3. SHOW CREATE TABLE users: avatar_media_id, uq_users_avatar_media_id,
--      fk_users_avatar_media.
--   4. SHOW CREATE TABLE communities: icon_media_id, banner_media_id, their
--      unique keys and foreign keys.
CREATE TABLE media (
    id VARCHAR(36) PRIMARY KEY,
    uploader_id VARCHAR(36) NULL,
    purpose ENUM('post', 'avatar', 'community_icon', 'community_banner') NOT NULL,
    kind ENUM('image', 'video') NOT NULL,
    mime_type VARCHAR(50) NOT NULL,
    size_bytes INT UNSIGNED NOT NULL,
    width INT UNSIGNED NULL,
    height INT UNSIGNED NULL,
    storage_key VARCHAR(200) NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    released_at TIMESTAMP NULL DEFAULT NULL,
    UNIQUE KEY uq_media_storage_key (storage_key),
    INDEX idx_media_uploader_pending (uploader_id, released_at, created_at),
    INDEX idx_media_released (released_at),
    CONSTRAINT fk_media_uploader FOREIGN KEY (uploader_id) REFERENCES users(id) ON DELETE SET NULL
);

ALTER TABLE posts
  ADD COLUMN media_id VARCHAR(36) NULL,
  ADD CONSTRAINT uq_posts_media_id UNIQUE (media_id),
  ADD CONSTRAINT fk_posts_media FOREIGN KEY (media_id) REFERENCES media(id);

ALTER TABLE users
  ADD COLUMN avatar_media_id VARCHAR(36) NULL,
  ADD CONSTRAINT uq_users_avatar_media_id UNIQUE (avatar_media_id),
  ADD CONSTRAINT fk_users_avatar_media FOREIGN KEY (avatar_media_id) REFERENCES media(id);

ALTER TABLE communities
  ADD COLUMN icon_media_id VARCHAR(36) NULL,
  ADD COLUMN banner_media_id VARCHAR(36) NULL,
  ADD CONSTRAINT uq_communities_icon_media_id UNIQUE (icon_media_id),
  ADD CONSTRAINT uq_communities_banner_media_id UNIQUE (banner_media_id),
  ADD CONSTRAINT fk_communities_icon_media FOREIGN KEY (icon_media_id) REFERENCES media(id),
  ADD CONSTRAINT fk_communities_banner_media FOREIGN KEY (banner_media_id) REFERENCES media(id);
